using System;using UnityEngine;using UnityEditor;using Conquest.WorldMap;
public static class ValidateLocalCampaignNavigation {
 public static string Run(){var c=UnityEngine.Object.FindAnyObjectByType<WorldMapCampaignController>();var grid=c.navigation;if(grid.sourceSHA256!=c.streamer.manifest.sourceSHA256)throw new Exception("Wrong map");var a=c.cityA.GetComponent<WorldMapSettlementTarget>().entrance;var b=c.cityB.GetComponent<WorldMapSettlementTarget>().entrance;var watch=System.Diagnostics.Stopwatch.StartNew();if(!grid.TryRoute(a,b,out var route,out var error))throw new Exception(error);for(int i=1;i<route.Length;i++)if(!grid.SegmentClear(route[i-1],route[i]))throw new Exception("Route crosses blocked cell");var milliseconds=watch.ElapsedMilliseconds;
  var test=ScriptableObject.CreateInstance<WorldMapLocalNavigation>();try{test.columns=test.rows=7;test.cellSize=10;test.blocked=new byte[49];test.heights=new float[49];for(int z=0;z<7;z++)test.blocked[z*7+3]=3;test.blocked[5*7+3]=0;var start=new Vector3(15,0,15);var end=new Vector3(55,0,15);if(!test.TryRoute(start,end,out var detour,out error)||detour.Length<=2)throw new Exception("No detour around water");for(int i=1;i<detour.Length;i++)if(!test.SegmentClear(detour[i-1],detour[i]))throw new Exception("Detour crossed water");test.blocked[5*7+3]=3;if(test.TryRoute(start,end,out _,out _))throw new Exception("Crossed closed barrier");if(test.TryRoute(start,new Vector3(-1,0,1),out _,out _))throw new Exception("Allowed outside destination");Array.Clear(test.blocked,0,49);test.blocked[1]=test.blocked[7]=3;if(test.SegmentClear(new Vector3(5,0,5),new Vector3(15,0,15)))throw new Exception("Diagonal corner clipping");}finally{UnityEngine.Object.DestroyImmediate(test);}
  string report=$"Local A/B: {route.Length} route points, {milliseconds} ms measured in Editor; all segments clear. Synthetic: detour around water; closed barrier rejected; outside destination rejected; diagonal corner blocked. Grid {grid.columns}x{grid.rows}; cells {grid.cellSize}u; source SHA matches manifest.";System.IO.File.WriteAllText("Docs/LocalNavigationValidation.txt",report);return report;}
}
